// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.sudicideAnyone() {
            // If call succeeded, caller must be the owner
            assertTrue(caller == c.smartfix_owner());
        } catch {
            // If call reverted, caller must not be the owner
            assertTrue(caller != c.smartfix_owner());
        }
    }
}

